UPDATE public.vault_articles SET title = $v$Nutrition: Four Levers, One Pattern$v$, subtitle = $v$Protein, fuel around training, a Mediterranean base, caffeine as a tool$v$, summary = $v$Four levers: a protein floor, carbohydrate around training, a Mediterranean base for the rest, and caffeine used on purpose. This shelf is those four, then five things to cook and drink.$v$, evidence_tier = $v$strong$v$, protocol = $v${}$v$::jsonb, benefits = ARRAY[$v$A model for every food decision$v$, $v$An order that stops the fad cycle$v$, $v$Sets up the eight lessons that follow$v$], risks = ARRAY[$v$Not a substitute for a dietitian or a clinician with a diagnosed condition$v$, $v$Eating disorders: this shelf counts grams; if counting is the problem, skip the counting lessons and talk to someone$v$], body_md = $v$**Patterns, not diets**
A diet is a short-term identity. A pattern is how you eat when nobody is watching, on a Tuesday in November. This shelf teaches a pattern, in four levers, and then gives you five things to do with it in a kitchen.

**The four levers**
Protein first, because under-eating it is the most common and most expensive mistake active adults make, and the evidence for the dose is the cleanest in the field (Phillips and Van Loon 2011). Carbohydrate around training second, because the session is the highest-leverage hour of the day and it runs on glycogen. The Mediterranean pattern third, because it is the base the other meals sit on, and it has more long-term outcome data than any alternative. Caffeine last, because it is a multiplier on the first three and a foundation for nothing.

**What this shelf skips**
Calorie targets, which depend on the goal; the scale and a fortnight of honest tracking tell you more than a formula. Supplements past protein, most of which have weaker evidence than the food they claim to replace. The frameworks with a name and a flag: carnivore, fruitarian, fasting as a religion. None beats the Mediterranean pattern in outcome data, and every one of them is harder to keep on a Tuesday in November.

**The order matters**
Fix protein and the appetite settles. Place carbohydrate around training and the sessions improve. Build the base and the numbers on the Longevity shelf move. Then decide what to do with coffee. Most people start at the end.

**How to read this shelf**
Nine lessons. Four principles with numbers, then a breakfast, a plate, a bottle and a gut. Each ends with a practice you can do at the next meal.$v$, why_it_matters = $v$Without a model, food is a checklist and checklists get abandoned in three weeks. Four levers in order is a model you can carry into any kitchen and any country.$v$, try_today = ARRAY[$v$Audit the last 24 hours against the four levers. Which one was weakest?$v$, $v$Fix that one at the next meal; do not fix all four.$v$, $v$Read lesson 2 tomorrow, with your bodyweight in kilos to hand.$v$], key_takeaways = ARRAY[$v$Four levers, in order: protein, carbohydrate around training, the Mediterranean base, caffeine.$v$, $v$Patterns survive holidays and bad weeks; diets do not.$v$, $v$Fix the weakest lever first, not all four.$v$], quiz = $v$[{"q": "What is the difference between a diet and a pattern?", "choices": ["A diet is short-term and named; a pattern is how you eat when nobody is watching", "Diets are healthier", "None"], "correct": 0, "explain": "Patterns survive the holiday and the bad week. The Mediterranean evidence is strong because it is a pattern people keep."}, {"q": "Which lever comes first for active adults?", "choices": ["Caffeine", "Protein", "Avoiding seed oils"], "correct": 1, "explain": "Under-eating protein is the most common and most expensive nutrition mistake; fixing it has the largest single effect."}]$v$::jsonb, references_json = $v$[{"author": "Phillips, S. M. & Van Loon, L. J. C.", "title": "Dietary protein for athletes: from requirements to optimum adaptation (J. Sports Sci.)", "year": 2011}, {"author": "Thomas, D. T., Erdman, K. A. & Burke, L. M.", "title": "Position of the Academy of Nutrition and Dietetics, Dietitians of Canada, and the American College of Sports Medicine: nutrition and athletic performance (J. Acad. Nutr. Diet.)", "year": 2016}]$v$::jsonb, reflect_prompt = $v$Which of the four levers do you think about most, and which one actually needs the attention?$v$, integrate_prompt = $v$You fixed one lever for a week. What changed at the table, and what changed in training?$v$, practice_minutes = 5, lesson_number = 1, display_order = 1, course_role = $v$foundations$v$, read_time_min = 2, updated_at = now() WHERE slug = 'foundations-performance-nutrition';

UPDATE public.vault_articles SET title = $v$Protein: 1.6–2.2 g/kg a Day$v$, subtitle = $v$The one nutrition number worth tracking$v$, summary = $v$1.6–2.2 g/kg/day of protein, in three or four meals of about 0.4 g/kg each, is the highest-leverage nutrition lever there is. Below the floor you leave muscle, recovery and appetite control on the table.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "Daily", "frequency": "3 or 4 meals, about 0.4 g/kg per meal", "intensity": "1.6–2.2 g/kg/day", "prerequisites": "Healthy kidney function"}$v$::jsonb, benefits = ARRAY[$v$More muscle from the same training$v$, $v$Lean mass kept during fat loss$v$, $v$Appetite that settles on its own$v$, $v$Slower loss of muscle with age$v$], risks = ARRAY[$v$Stage 3 or worse chronic kidney disease: a clinician sets the dose$v$, $v$Above 2.2 g/kg there is no further gain$v$, $v$Cost: eggs, dairy, tinned fish and legumes are the cheap anchors$v$], body_md = $v$**The dose**
Morton et al. (2018) pooled 49 trials and 1,863 adults who lifted weights while eating different amounts of protein. Gains in lean mass rose with intake up to a breakpoint of 1.62 g per kilo a day, and the confidence interval reached 2.2, which is where the range comes from. Above it the curve is flat: not harmful, not useful. For a 75 kg adult that is 120 to 165 g a day. The old recommended intake of 0.8 g per kilo is the amount that prevents deficiency in a sedentary adult; it is not the amount that builds anything.

**Why the split matters**
Each protein-rich meal raises muscle protein synthesis for three to five hours and then it falls back, however much you ate. Schoenfeld and Aragon (2018) put the useful dose at about 0.4 g/kg per meal across four meals, which for a 75 kg adult is 30 g, and Mamerow et al. (2014) showed in a crossover trial that 90 g spread as 30, 30 and 30 drove about 25% more muscle protein synthesis over a day than the same 90 g eaten as 10, 15 and 65. Breakfast is where most people fall short. Over forty the muscle is less sensitive to each dose, and older adults need closer to 0.4 g/kg per meal to get the response a younger adult gets from less (Moore et al. 2015).

**Satiety**
Protein is the most filling macronutrient per calorie. Weigle et al. (2005) raised protein to 30% of calories with no other rule and watched free-living adults eat about 440 fewer calories a day and lose weight without trying. This is why the protein lever settles appetite before it does anything else.

**Leucine**
The amino acid that trips the synthesis switch. About 2.5 to 3 g per meal does it: an egg has half a gram, a chicken breast three, a scoop of whey two and a half. Most plant proteins need a larger serving to reach it, which is fine; it is a serving size, not a barrier.

**How to run it**
Anchor every meal with a palm-sized portion of meat, fish, eggs, dairy, tofu or legumes. Get 30 g in at breakfast; lesson 6 has three ways. Keep whey or skyr as a fast top-up. Track for one week, then stop; once you know what 30 g looks like on a plate the count runs itself.$v$, why_it_matters = $v$Of every nutrition variable studied, daily protein has the largest effect on body composition, recovery and appetite. Most active adults are 30 to 50 g a day under the floor and blame the training.$v$, try_today = ARRAY[$v$Multiply your bodyweight in kilos by 1.6 and by 2.2. That is the daily range in grams.$v$, $v$Plan tomorrow so each of three or four meals carries about 0.4 g/kg per meal: a palm of meat or fish, 250 g of skyr, or a scoop of whey.$v$, $v$Track for three days. Most people are surprised how far under the floor they sit.$v$], key_takeaways = ARRAY[$v$1.6–2.2 g/kg/day; below the floor is under-dosed.$v$, $v$Three or four meals of about 0.4 g/kg per meal beat the same total in two.$v$, $v$Protein settles appetite first; the muscle follows.$v$], quiz = $v$[{"q": "Daily protein floor for an active 80 kg adult?", "choices": ["240 g", "64 g", "128 g"], "correct": 2, "explain": "80 times 1.6. The 64 g figure is the old deficiency-prevention intake, not a performance dose."}, {"q": "Why split protein across the day?", "choices": ["Each meal triggers a separate synthesis pulse; evenly spread doses beat one large one", "It saves money", "It tastes better"], "correct": 0, "explain": "Mamerow 2014: 30, 30 and 30 beat 10, 15 and 65 by about a quarter over a day."}, {"q": "In Weigle's 2005 trial, raising protein to 30% of calories…", "choices": ["Increased hunger", "Cut daily intake by about 440 calories without any other rule", "Changed nothing"], "correct": 1, "explain": "Free-living adults, no calorie target, and they ate less and lost weight."}]$v$::jsonb, references_json = $v$[{"author": "Morton, R. W. et al.", "title": "A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults (Br. J. Sports Med.)", "year": 2018}, {"author": "Schoenfeld, B. J. & Aragon, A. A.", "title": "How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution (J. Int. Soc. Sports Nutr.)", "year": 2018}, {"author": "Mamerow, M. M. et al.", "title": "Dietary protein distribution positively influences 24-h muscle protein synthesis in healthy adults (J. Nutr.)", "year": 2014}, {"author": "Weigle, D. S. et al.", "title": "A high-protein diet induces sustained reductions in appetite, ad libitum caloric intake, and body weight despite compensatory changes in diurnal plasma leptin and ghrelin concentrations (Am. J. Clin. Nutr.)", "year": 2005}, {"author": "Moore, D. R. et al.", "title": "Protein ingestion to stimulate myofibrillar protein synthesis requires greater relative protein intakes in healthy older versus younger men (J. Gerontol. A)", "year": 2015}]$v$::jsonb, reflect_prompt = $v$How much protein did breakfast carry today, in grams, and do you actually know?$v$, integrate_prompt = $v$After a week at the floor, what happened to hunger in the evening?$v$, practice_minutes = 10, lesson_number = 2, display_order = 2, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'protein-1-6-2-2-g-kg';

UPDATE public.vault_articles SET title = $v$Fuelling Around Training$v$, subtitle = $v$Carbohydrate before and after, and when the window actually closes$v$, summary = $v$Hard training runs on glycogen. Eat 1–2 g/kg of carbohydrate with 20–40 g of protein one to three hours before, refuel with 0.3 g/kg of protein within two hours after, and forget the thirty-minute window; it never existed.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "Around each session", "frequency": "Every training day", "intensity": "Before: 1–2 g/kg carbohydrate with 20–40 g protein · During, past 75 min: 30–60 g an hour · After: 0.3 g/kg protein within 2 h", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$More reps and higher output in hard sessions$v$, $v$Faster glycogen refill between sessions$v$, $v$Readiness for the next day$v$, $v$Less muscle breakdown$v$], risks = ARRAY[$v$Fasted training is fine for sessions under an hour; do not force food$v$, $v$High-fibre or high-fat meals right before training upset the gut$v$, $v$Diabetes: carbohydrate during a session is planned with your clinician$v$], body_md = $v$**The three windows**
The International Society of Sports Nutrition's position on nutrient timing (Kerksick et al. 2017) consolidates thirty years of trials into three windows. Before: 1–2 g/kg of carbohydrate with 20–40 g of protein, one to three hours out. For a 75 kg lifter that is 75 to 150 g of carbohydrate, which is a bowl of oats with a banana and a pot of skyr. During: only for sessions past 75 minutes or two sessions in a day, 30–60 g of carbohydrate an hour from a drink, a gel or fruit; Jeukendrup (2014) showed the gut absorbs more when glucose and fructose are mixed. After: about 0.3 g/kg of protein, which is 20 to 25 g for most people, plus carbohydrate scaled to the session, within two hours.

**The window that was a myth**
The thirty-minute anabolic window came from studies that trained people fasted and then fed them; the feeding looked urgent because the subjects were empty. Aragon and Schoenfeld (2013) went through the evidence and found the window at least two hours wide when a meal was eaten before training, and total daily protein mattering more than the timing of any one dose. A normal meal within two hours is the rule. The shake in the changing room is a convenience, not a requirement.

**What actually moves the session**
Carbohydrate on board raises the quality of a hard session: more reps at the same load, higher average power on the bike. Hydration matters at least as much; the Sawka et al. (2007) position stand puts the performance cost at a 2% loss of body mass, which is a litre and a half for a 75 kg person and easy to reach in a hot gym. And daily totals beat any window: if protein and carbohydrate are right across the day, a missed post-session meal costs nothing measurable.

**Practical defaults**
Lifting early and fasted: a coffee, 20 g of whey and a banana is enough. Training after work: a proper lunch three to four hours before, and 30 g of easy carbohydrate half an hour before if the energy is low. Endurance past ninety minutes: 60 g of carbohydrate an hour, packed before you leave. Rest days: carbohydrate down, protein the same.

**The one rule**
Scale carbohydrate to the work. Hard days more, rest days less, protein constant.$v$, why_it_matters = $v$Most people either fear carbohydrate or eat it at random. Both leak training quality. Placing it around the session lifts the session without changing what you eat across the week.$v$, try_today = ARRAY[$v$Before the next session: 1–2 g/kg of carbohydrate with 20–40 g of protein, one to three hours out.$v$, $v$After: a real meal within two hours, with about 0.3 g/kg of protein.$v$, $v$Weigh yourself before and after one hot session; every kilo lost is a litre to drink back.$v$], key_takeaways = ARRAY[$v$Before: 1–2 g/kg carbohydrate plus 20–40 g protein, one to three hours out.$v$, $v$After: 0.3 g/kg protein within two hours; the thirty-minute window was a myth.$v$, $v$Carbohydrate scales to the work; protein stays constant.$v$], quiz = $v$[{"q": "For a 60-minute strength session, carbohydrate during the session is…", "choices": ["Banned", "Essential", "Unnecessary; it matters past about 75 minutes"], "correct": 2, "explain": "Glycogen covers an hour easily. Intra-session carbohydrate earns its place in long or doubled sessions."}, {"q": "How wide is the post-training protein window?", "choices": ["At least two hours, when a meal was eaten before training", "Twenty-four hours", "Thirty minutes"], "correct": 0, "explain": "Aragon and Schoenfeld 2013. Daily totals matter more than the clock."}, {"q": "At what fluid loss does performance measurably drop?", "choices": ["0.1% of body mass", "About 2% of body mass", "10% of body mass"], "correct": 1, "explain": "Sawka 2007. A litre and a half for a 75 kg person, one hot session's worth."}]$v$::jsonb, references_json = $v$[{"author": "Kerksick, C. M. et al.", "title": "International Society of Sports Nutrition position stand: nutrient timing (J. Int. Soc. Sports Nutr.)", "year": 2017}, {"author": "Aragon, A. A. & Schoenfeld, B. J.", "title": "Nutrient timing revisited: is there a post-exercise anabolic window? (J. Int. Soc. Sports Nutr.)", "year": 2013}, {"author": "Jeukendrup, A.", "title": "A step towards personalized sports nutrition: carbohydrate intake during exercise (Sports Med.)", "year": 2014}, {"author": "Sawka, M. N. et al.", "title": "American College of Sports Medicine position stand: exercise and fluid replacement (Med. Sci. Sports Exerc.)", "year": 2007}]$v$::jsonb, reflect_prompt = $v$What did you eat before your last hard session, and how many hours before?$v$, integrate_prompt = $v$A week of placed carbohydrate. Did the sessions feel different, and which ones?$v$, practice_minutes = 10, lesson_number = 3, display_order = 3, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'workout-fueling-stack';

UPDATE public.vault_articles SET title = $v$The Mediterranean Pattern$v$, subtitle = $v$The most-studied way of eating, and what its evidence is worth$v$, summary = $v$Vegetables, legumes, whole grains, nuts, olive oil as the fat, fish twice a week, red meat as a guest. One large trial and sixty years of cohorts sit behind it; the chip says promising because the trial was imperfect and the mortality data are observational.$v$, evidence_tier = $v$promising$v$, protocol = $v${"duration": "A lifetime pattern", "frequency": "Daily", "intensity": "Vegetables at every main meal · fish twice a week · olive oil as the fat · nuts daily · red meat about weekly", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$Fewer cardiovascular events in the one large trial$v$, $v$Lower mortality and dementia risk across cohorts$v$, $v$Better lipids and insulin sensitivity$v$, $v$Works in most cuisines and on most budgets$v$], risks = ARRAY[$v$Olive oil is calorie-dense; measure it if fat loss is the goal$v$, $v$Cost in some regions; tinned fish, beans and frozen vegetables close the gap$v$, $v$Fish allergy: plant omega-3 sources and a clinician's advice$v$, $v$Wine is not part of the recommendation; the alcohol evidence has moved$v$], body_md = $v$**What it is**
Not a diet with a start date. A way of eating documented around the coasts of Greece, southern Italy and Spain in the 1950s and 60s: plants as the base, olive oil as the fat, fish and legumes as the protein, dairy and poultry in moderation, red meat rarely, almost nothing ultra-processed. Wine with meals in the original, which is a cultural note and not a recommendation; the alcohol evidence has moved, and none is the safe dose.

**The evidence**
The PREDIMED trial (Estruch et al. 2018) randomised 7,447 Spanish adults at high cardiovascular risk to a Mediterranean pattern with extra olive oil, the same pattern with nuts, or a low-fat control. Over about five years, both Mediterranean arms had roughly 30% fewer major cardiovascular events. The trial was withdrawn and republished in 2018 after problems with how some sites randomised participants; the corrected analysis held. It remains the largest dietary trial with hard outcomes, and it is one trial. The Lyon Diet Heart Study (de Lorgeril et al. 1999) found a large drop in repeat cardiac events in heart attack survivors on a similar pattern; it was small and stopped early, which inflates effects. The cohort data are the bulk of the sixty years: Sofi et al. (2008) pooled them and found each two-point rise in adherence tracked with 9% lower overall mortality, 9% lower cardiovascular mortality, 6% lower cancer incidence or mortality and 13% lower Parkinson's and Alzheimer's. Associations, consistently in one direction, across more than a million people.

**Why promising and not strong**
The chip rates the evidence for the practice as written. One large trial with a repaired randomisation and cohorts for the rest is the honest description. It is the best-evidenced eating pattern there is, and that is a statement about the alternatives as much as about this one.

**How to start**
Vegetables the largest item on the plate at lunch and dinner. Extra-virgin olive oil as the default fat; measure it if fat loss is the goal, because it is calorie-dense. Fish twice a week, tinned counts. Nuts and fruit as the snack. Red meat about once a week. The ten-minute plate in lesson 7 is this pattern in a hurry.$v$, why_it_matters = $v$No way of eating has more long-term outcome data. It is not a cleanse or a phase. It is the default the other meals sit on, and it compounds over decades.$v$, try_today = ARRAY[$v$Add one fish meal this week: sardines, salmon, mackerel or anchovies, tinned is fine.$v$, $v$Cook today's dinner in extra-virgin olive oil instead of butter.$v$, $v$Make half the plate vegetables and put a handful of nuts where the biscuits were.$v$], key_takeaways = ARRAY[$v$Plants, olive oil, fish, nuts; red meat as a guest.$v$, $v$About 30% fewer cardiovascular events in the one large trial; 9% lower mortality per two adherence points in the cohorts.$v$, $v$Promising, not strong: one repaired trial plus observational data, and still the best-evidenced pattern there is.$v$], quiz = $v$[{"q": "What is the cornerstone fat?", "choices": ["Coconut oil", "Butter", "Extra-virgin olive oil"], "correct": 2, "explain": "Monounsaturated fat and polyphenols; PREDIMED's olive-oil arm used about four tablespoons a day."}, {"q": "Why does the chip say promising rather than strong?", "choices": ["One large trial with a repaired randomisation, and cohort data for the mortality claims", "Nobody has studied it", "The pattern does not work"], "correct": 0, "explain": "The chip rates the evidence for the practice as written, and that is the honest description."}, {"q": "The Mediterranean pattern is best described as…", "choices": ["A 1,500-calorie diet", "A flexible pattern of food choices, not a calorie rule", "A keto variant"], "correct": 1, "explain": "It defines what and in what proportion, not how much, which is why it adapts to any goal."}]$v$::jsonb, references_json = $v$[{"author": "Estruch, R. et al.", "title": "Primary prevention of cardiovascular disease with a Mediterranean diet supplemented with extra-virgin olive oil or nuts (N. Engl. J. Med.)", "year": 2018}, {"author": "de Lorgeril, M. et al.", "title": "Mediterranean diet, traditional risk factors, and the rate of cardiovascular complications after myocardial infarction: final report of the Lyon Diet Heart Study (Circulation)", "year": 1999}, {"author": "Sofi, F., Cesari, F., Abbate, R., Gensini, G. F. & Casini, A.", "title": "Adherence to Mediterranean diet and health status: meta-analysis (BMJ)", "year": 2008}]$v$::jsonb, reflect_prompt = $v$Which of the pattern's pieces is already on your plate, and which one has never been?$v$, integrate_prompt = $v$Two weeks with fish twice and olive oil as the default. What did you stop eating without deciding to?$v$, practice_minutes = 15, lesson_number = 4, display_order = 4, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'mediterranean-pattern';

UPDATE public.vault_articles SET title = $v$Caffeine as a Performance Tool$v$, subtitle = $v$3–6 mg per kilo an hour before the effort, and the cut-off that protects the night$v$, summary = $v$Caffeine is the best-studied legal performance aid there is. Take 3–6 mg per kilo about an hour before a hard session, keep the last dose 8–10 h before bed, and take a week off now and then so it keeps working.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "Acute", "frequency": "Before hard sessions; not daily if the effect matters", "intensity": "3–6 mg per kilo, about 60 minutes before", "prerequisites": "Adult; no arrhythmia; in pregnancy no more than 200 mg a day"}$v$::jsonb, benefits = ARRAY[$v$A few percent on endurance, strength and power$v$, $v$Lower perceived exertion$v$, $v$Sharper focus and reaction time$v$, $v$Cheap, legal and well tolerated$v$], risks = ARRAY[$v$Half-life 5–7 h; the afternoon dose is in the bed with you$v$, $v$Tolerance in about two weeks of daily use$v$, $v$Pregnancy: 200 mg a day at most$v$, $v$Anxiety, reflux, hypertension, arrhythmia: a clinician first$v$], body_md = $v$**The dose**
Grgic et al. (2020) reviewed 21 meta-analyses and found caffeine improves endurance, strength and power by a few percent, with the effect clearest at 3–6 mg per kilo taken about 60 minutes before the effort; the International Society of Sports Nutrition's position stand (Guest et al. 2021) lands in the same place. For a 75 kg adult that is 225 to 450 mg. A strong coffee carries about 100 to 120 mg, an espresso 60 to 80, a pre-workout scoop 150 to 300. Start at the low end. More than 6 mg per kilo adds side effects, not performance.

**Timing**
Absorption peaks around 45 to 75 minutes. Take it an hour before the session or the hardest hour of thinking. The other timing rule is the one that protects sleep, and it lives in The Caffeine Cut-Off on the Recovery shelf: half-life 5–7 h, last dose 8–10 h before bed. Two rules, one substance: an hour before the work, none after early afternoon.

**Tolerance**
Daily use dulls the performance effect. Lara et al. (2019) gave 3 mg per kilo every day for twenty days and watched the boost to cycling power fade over the first fortnight. Keep the effect for the sessions that matter: skip caffeine on rest days, or take a full week off each quarter and bring it back before a hard block.

**Who takes less**
Pregnancy: the consensus cap is 200 mg a day, and the half-life roughly doubles. Slow metabolisers, which about a fifth of people are, feel the anxiety and the sleep cost at lower doses. Anyone with an arrhythmia, uncontrolled blood pressure, reflux or an anxiety disorder talks to a clinician before using caffeine as a tool rather than a drink.

**When to skip it**
Within ninety minutes of an evening session, because the dose that helps the session will be in the bed with you. Before a presentation if nerves, not sleepiness, are the problem; caffeine amplifies both.$v$, why_it_matters = $v$The same substance is a performance aid at 07:00 and a sleep tax at 16:00. Used on purpose it lifts the hard sessions and leaves the night alone; used as a drink it does neither.$v$, try_today = ARRAY[$v$Work out your dose: bodyweight in kilos times 3 to 6, in milligrams. Start at 3.$v$, $v$Take it an hour before the next hard session and write down how the session went.$v$, $v$Skip it on the next two rest days and see what a fresh dose does the day after.$v$], key_takeaways = ARRAY[$v$3–6 mg per kilo, an hour before the effort, starting low.$v$, $v$Last dose 8–10 h before bed; the performance rule and the sleep rule are one substance.$v$, $v$Rest days off and one week a quarter off keep it working.$v$], quiz = $v$[{"q": "A 70 kg athlete's evidence-based pre-session dose?", "choices": ["1,000 mg", "50 mg", "210 to 420 mg"], "correct": 2, "explain": "3 to 6 mg per kilo. Two to four espressos, and start at the low end."}, {"q": "After twenty days of daily caffeine, Lara's 2019 trial found…", "choices": ["The performance boost faded over the first two weeks", "No change", "A bigger effect"], "correct": 0, "explain": "Tolerance to the ergogenic effect builds fast. Rest days off, or a week off a quarter, keeps it."}, {"q": "Caffeine within ninety minutes of an evening session…", "choices": ["Costs nothing", "Is still active at bedtime; the session gains, the night pays", "Builds muscle"], "correct": 1, "explain": "Half-life 5–7 h. The evening dose and the sleep dose are the same molecule."}]$v$::jsonb, references_json = $v$[{"author": "Grgic, J. et al.", "title": "Wake up and smell the coffee: caffeine supplementation and exercise performance, an umbrella review of 21 published meta-analyses (Br. J. Sports Med.)", "year": 2020}, {"author": "Guest, N. S. et al.", "title": "International Society of Sports Nutrition position stand: caffeine and exercise performance (J. Int. Soc. Sports Nutr.)", "year": 2021}, {"author": "Lara, B., Ruiz-Moreno, C., Salinero, J. J. & Del Coso, J.", "title": "Time course of tolerance to the performance benefits of caffeine (PLoS One)", "year": 2019}]$v$::jsonb, reflect_prompt = $v$Is coffee a tool for you or a habit, and which sessions would you spend it on if it were rationed?$v$, integrate_prompt = $v$Two rest days without caffeine and one hard session with it. What did the dose feel like when it was fresh?$v$, practice_minutes = 5, lesson_number = 5, display_order = 5, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'caffeine-timing';

UPDATE public.vault_articles SET title = $v$Three Breakfasts That Hit the Protein Dose$v$, subtitle = $v$About 30 to 40 g before you leave the house, in six minutes$v$, summary = $v$Most people eat their protein at dinner and their carbohydrate at breakfast, which is backwards. Three real-food breakfasts that each land 30 to 40 g of protein in six minutes or less.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "6 min", "frequency": "Every morning", "intensity": "About 30 to 40 g of protein", "prerequisites": "None"}$v$::jsonb, benefits = ARRAY[$v$The day's protein total moves before the day starts$v$, $v$Steadier morning energy and less mid-morning snacking$v$, $v$Less evening grazing$v$], risks = ARRAY[$v$Figures are approximate and vary by brand; weigh once, then estimate$v$, $v$Lactose intolerance: lactose-free skyr and whey isolate carry the same protein$v$, $v$If breakfast is genuinely impossible, the same dose an hour later is fine; the point is the split, not the clock$v$], body_md = $v$**Why breakfast**
The protein lesson sets the meal dose at about 0.4 g/kg per meal, which is 30 g for a 75 kg adult and closer to 40 g for a 95 kg one. Breakfast is where the day's protein is usually missing. Mamerow et al. (2014) fed the same daily protein as 30, 30 and 30 or as 10, 15 and 65 and measured about 25% more muscle protein synthesis over the day from the even split; the skewed pattern is how most people eat. Leidy et al. (2013) gave habitual breakfast-skippers a 35 g protein breakfast and watched evening snacking on high-fat and high-sugar food fall compared with a cereal breakfast of the same calories. The morning dose pays twice: muscle now, appetite tonight.

**One: the savoury scramble, about 30 g**
Three eggs and 100 g of cottage cheese, whisked together and cooked with a handful of spinach. Salt, pepper, hot sauce. Three eggs bring about 19 g and the cottage cheese about 11; the pan is on and off in five minutes. Low in carbohydrate, so it suits a rest day or a morning without training.

**Two: the skyr bowl, about 40 g**
250 g of skyr or 0% Greek yoghurt, which carries about 25 g, with 20 g of whey stirred in for another 16. Berries on top, a spoon of honey if a session is coming. Two minutes, no cooking, and the highest dose of the three.

**Three: overnight oats with whey, about 40 g**
60 g of oats, 250 ml of milk, a scoop of whey, a tablespoon of chia, cinnamon. Stir in a jar the night before. The oats and milk bring about 16 g and the whey about 24. This is the training-morning build: the carbohydrate is there for the session.

**Pick by the day**
Scramble on a rest day, oats before a session, the bowl when there is no time at all. The figures are approximate and brand-dependent; once you have seen 30 g on a plate three times, you will not need to weigh it again.$v$, why_it_matters = $v$The cheapest place to fix the protein lever is the first meal, because that is where it is missing. Six minutes in the morning moves the whole day's total and the evening's appetite.$v$, try_today = ARRAY[$v$Make one of the three tomorrow morning; choose by whether you train.$v$, $v$Portion the oats tonight if it is the oats.$v$, $v$Note how hungry you are at 21:00 compared with a normal day.$v$], key_takeaways = ARRAY[$v$About 30 to 40 g at breakfast, about 0.4 g/kg per meal, rather than all of it at dinner.$v$, $v$An even split across the day drove about 25% more muscle protein synthesis in the crossover trial.$v$, $v$A 35 g protein breakfast cut evening snacking in breakfast-skippers; the morning dose pays at night.$v$], quiz = $v$[{"q": "Why front-load protein to breakfast?", "choices": ["Breakfast is the largest meal", "Protein is only absorbed in the morning", "Even doses across the day drive more synthesis, and the morning dose cuts evening snacking"], "correct": 2, "explain": "Mamerow 2014 for the synthesis, Leidy 2013 for the evening snacking."}, {"q": "Which build suits a training morning?", "choices": ["Overnight oats with whey", "Black coffee", "The scramble"], "correct": 0, "explain": "The oats carry the carbohydrate the session runs on; the scramble is the rest-day build."}]$v$::jsonb, references_json = $v$[{"author": "Mamerow, M. M. et al.", "title": "Dietary protein distribution positively influences 24-h muscle protein synthesis in healthy adults (J. Nutr.)", "year": 2014}, {"author": "Leidy, H. J. et al.", "title": "Beneficial effects of a higher-protein breakfast on the appetitive, hormonal, and neural signals controlling energy intake regulation in overweight/obese, breakfast-skipping, late-adolescent girls (Am. J. Clin. Nutr.)", "year": 2013}, {"author": "Schoenfeld, B. J. & Aragon, A. A.", "title": "How much protein can the body use in a single meal for muscle-building? Implications for daily protein distribution (J. Int. Soc. Sports Nutr.)", "year": 2018}]$v$::jsonb, reflect_prompt = $v$What did you eat for breakfast today, and how many grams of protein was it, honestly?$v$, integrate_prompt = $v$A week of 30 g breakfasts. What happened to the mid-morning hunger and the evening snacking?$v$, practice_minutes = 6, lesson_number = 6, display_order = 6, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'high-protein-breakfast-3-builds';

UPDATE public.vault_articles SET title = $v$The Ten-Minute Plate$v$, subtitle = $v$One formula instead of a hundred recipes$v$, summary = $v$A palm of protein, half a plate of plants, a cupped hand of carbohydrate scaled to training, a thumb of fat. One formula rebuilt from whatever is in the fridge, with three worked examples that take ten minutes.$v$, evidence_tier = $v$promising$v$, protocol = $v${"duration": "8 to 12 min", "frequency": "Any main meal", "intensity": "Palm · half a plate · cupped hand · thumb", "prerequisites": "A stocked freezer and two tins"}$v$::jsonb, benefits = ARRAY[$v$No recipe to remember$v$, $v$Macros balance by shape$v$, $v$Scales to any goal and any kitchen$v$], risks = ARRAY[$v$Hand measures are crude; if a goal needs precision, weigh for a week$v$, $v$Tinned fish and pouches carry salt; rinse beans and read the tin if blood pressure is a concern$v$], body_md = $v$**The formula**
Stop hunting recipes and learn one plate. A palm-sized portion of protein: chicken, fish, tofu, eggs, lean beef, a tin of something. Half the plate plants: vegetables, salad, frozen counts. A cupped hand of carbohydrate: rice, potato, beans, bread, scaled up on training days and down on rest days, which is the fuelling lesson applied at dinner. A thumb of fat: olive oil, avocado, nuts, seeds. Hand measures are crude and they are yours, which is why they work: they scale with the person and they travel.

**Why frozen and tinned count**
Bouzari et al. (2015) compared vitamin content in eight fruits and vegetables stored fresh in the fridge and frozen, and found frozen matched or beat fresh for most nutrients, because freezing happens hours from the field and the fridge is a slow decline. Tinned fish and beans are the same trade: convenience that keeps you consistent, with nothing meaningful lost. Consistency beats perfection at every meal you will ever eat.

**Three plates**
Twelve minutes: a salmon fillet under the grill, frozen broccoli in the microwave, a rice pouch, olive oil and lemon. Eight minutes: tinned tuna, a bag of salad, a tin of chickpeas rinsed, olive oil and vinegar. Ten minutes: pre-cooked chicken, frozen stir-fry vegetables in a hot pan, noodles, sesame oil and soy.

**What it is in disguise**
Plants underneath, olive oil for the fat, fish and beans for the protein: the Mediterranean pattern from lesson 4, built in a hurry. Estruch et al. (2018) did not test a formula; they tested a pattern, and this is the pattern in its weeknight clothes.

**Stocking the kitchen**
Three bags of frozen vegetables, two tins of fish, two of beans, a rice pouch, olive oil. With those on hand the plate is always eight minutes away, and the eight minutes are what stand between you and the takeaway.$v$, why_it_matters = $v$Decision fatigue at 19:00 is what beats most people's nutrition, not knowledge. One formula and a stocked freezer remove the decision.$v$, try_today = ARRAY[$v$Build tonight's dinner from the formula without a recipe.$v$, $v$Stock three bags of frozen vegetables and two tins of fish this week.$v$, $v$On the next training day, double the carbohydrate hand; on the next rest day, halve it.$v$], key_takeaways = ARRAY[$v$Palm of protein, half a plate of plants, a cupped hand of carbohydrate, a thumb of fat.$v$, $v$Frozen and tinned are not a compromise; they are how consistency happens.$v$, $v$Scale the carbohydrate to the day's training; the rest of the plate stays.$v$], quiz = $v$[{"q": "How much carbohydrate goes on the plate?", "choices": ["Always none", "A cupped hand, scaled to that day's training", "Half the plate"], "correct": 1, "explain": "More on training days, less on rest days; protein and plants stay the same."}, {"q": "Frozen vegetables compared with fresh from the fridge…", "choices": ["Are unsafe", "Lose most vitamins", "Match or beat fresh for most nutrients"], "correct": 2, "explain": "Bouzari 2015: freezing happens hours from the field; the fridge is a slow decline."}]$v$::jsonb, references_json = $v$[{"author": "Bouzari, A., Holstege, D. & Barrett, D. M.", "title": "Vitamin retention in eight fruits and vegetables: a comparison of refrigerated and frozen storage (J. Agric. Food Chem.)", "year": 2015}, {"author": "Estruch, R. et al.", "title": "Primary prevention of cardiovascular disease with a Mediterranean diet supplemented with extra-virgin olive oil or nuts (N. Engl. J. Med.)", "year": 2018}]$v$::jsonb, reflect_prompt = $v$What decides dinner on a normal Tuesday, a plan or the fridge at 19:00?$v$, integrate_prompt = $v$A week of the formula. How many nights did the takeaway lose?$v$, practice_minutes = 10, lesson_number = 7, display_order = 7, course_role = $v$protocol$v$, read_time_min = 2, updated_at = now() WHERE slug = 'ten-minute-performance-plate';

UPDATE public.vault_articles SET title = $v$Hydration and Electrolytes$v$, subtitle = $v$How much, how to tell, and when plain water is the wrong answer$v$, summary = $v$Mild dehydration, one to two percent of body mass, measurably dulls mood and focus and costs performance. Drink to pale urine, count coffee and tea, and add sodium only around heavy sweat.$v$, evidence_tier = $v$strong$v$, protocol = $v${"duration": "All day", "frequency": "A glass on waking, one with each meal, a bottle at the desk", "intensity": "About 30 to 35 ml per kilo; about 500 mg of sodium per litre around heavy sweat", "prerequisites": "Kidney or heart conditions: follow medical advice on fluid and salt"}$v$::jsonb, benefits = ARRAY[$v$Sharper focus and steadier mood$v$, $v$Better training output in heat$v$, $v$Fewer afternoon headaches$v$], risks = ARRAY[$v$Kidney or heart disease: fluid and sodium are set by your clinician$v$, $v$Litres of plain water after heavy sweat can drop blood sodium; add salt$v$, $v$Clear urine all day is too much, not a badge$v$], body_md = $v$**The baseline**
Total water needs run around 30 to 35 ml per kilo a day for most adults, more in heat and with training, and roughly a fifth of it comes from food. The European Food Safety Authority puts adequate total intake at 2 litres a day for women and 2.5 for men, which is the same arithmetic. The best gauge is not a number, it is the colour of the first urine of the day: pale straw is right, clear means too much, dark means catch up.

**What mild dehydration does**
Armstrong et al. (2012) dehydrated healthy young women by about 1.4% of body mass, with and without exercise, and measured worse mood, more headaches and harder concentration; Ganio et al. (2011) found the same in men at 1.6%. The performance cost starts around a 2% loss of body mass (Sawka et al. 2007), which in a hot gym is an hour of hard work for many people. Thirst lags the loss, so the rule is to drink before it arrives.

**Coffee counts**
Killer et al. (2014) had regular coffee drinkers take four cups a day for three days and compared their hydration with the same volume of water. No difference in total body water or in any hydration marker. The diuretic effect of caffeine is real in people who never drink it and vanishes with habit. Tea and coffee go in the daily total.

**When water is the wrong answer**
Sweat carries sodium out, around a gram per litre for a typical sweater and much more for a salty one. Long or hot sessions, sauna days and very low-carbohydrate eating all lose it faster. Replacing litres of sweat with plain water dilutes what is left and can end in headache, cramp and, in extreme cases, a dangerous drop in blood sodium. The fix is not a sachet: a pinch of salt in the bottle, about 500 mg of sodium per litre, with a squeeze of citrus, during and after heavy sweat sessions.

**The daily habit**
A glass on waking, since the night is eight hours of losses. One with each meal. The bottle at the desk. On sweaty days, salt in it.$v$, why_it_matters = $v$Two percent down is the difference between a good session and a flat one, and you will not feel thirsty until you are already there. The gauge is free and it is in the toilet bowl every morning.$v$, try_today = ARRAY[$v$Drink a full glass of water on waking tomorrow, before the coffee.$v$, $v$Check the colour of the first urine: pale straw is the target.$v$, $v$On the next sweaty session, put a pinch of salt in the bottle.$v$], key_takeaways = ARRAY[$v$About 30 to 35 ml per kilo a day, judged by urine colour, not a fixed number.$v$, $v$Coffee and tea count in the total.$v$, $v$Sodium only around heavy sweat; plain water alone can backfire there.$v$], quiz = $v$[{"q": "Do coffee and tea count toward daily fluid?", "choices": ["Yes; in habitual drinkers there is no measurable diuretic effect", "Only decaf", "No, caffeine dehydrates"], "correct": 0, "explain": "Killer 2014: four cups a day for three days, no difference from the same volume of water."}, {"q": "When does plain water become the wrong answer?", "choices": ["Always", "After heavy sweat, when sodium needs replacing too", "In winter"], "correct": 1, "explain": "Sweat carries about a gram of sodium per litre; litres of plain water dilute what is left."}, {"q": "What colour is the first urine of the day when hydration is right?", "choices": ["Dark amber", "Clear", "Pale straw"], "correct": 2, "explain": "Clear is too much, dark is too little. Pale straw is the target."}]$v$::jsonb, references_json = $v$[{"author": "Sawka, M. N. et al.", "title": "American College of Sports Medicine position stand: exercise and fluid replacement (Med. Sci. Sports Exerc.)", "year": 2007}, {"author": "Armstrong, L. E. et al.", "title": "Mild dehydration affects mood in healthy young women (J. Nutr.)", "year": 2012}, {"author": "Ganio, M. S. et al.", "title": "Mild dehydration impairs cognitive performance and mood of men (Br. J. Nutr.)", "year": 2011}, {"author": "Killer, S. C., Blannin, A. K. & Jeukendrup, A. E.", "title": "No evidence of dehydration with moderate daily coffee intake: a counterbalanced cross-over study in a free-living population (PLoS One)", "year": 2014}, {"author": "European Food Safety Authority", "title": "Scientific opinion on dietary reference values for water (EFSA Journal)", "year": 2010}]$v$::jsonb, reflect_prompt = $v$What colour was this morning's first urine, and did you notice?$v$, integrate_prompt = $v$A week with the glass on waking and the bottle at the desk. What happened to the afternoon headaches?$v$, practice_minutes = 3, lesson_number = 8, display_order = 8, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'hydration-electrolytes-baseline';

UPDATE public.vault_articles SET title = $v$Gut Health: Fibre, Fermented Foods and Diversity$v$, subtitle = $v$Two levers with evidence, and the one that surprised the trial$v$, summary = $v$The gut microbiome shapes digestion, immunity and probably mood. Two levers feed it: thirty different plants a week, and a small daily serving of fermented food, which in the one controlled trial did more for diversity than fibre did in ten weeks.$v$, evidence_tier = $v$promising$v$, protocol = $v${"duration": "Daily", "frequency": "Thirty different plants a week; one fermented serving a day", "intensity": "25 to 30 g of fibre a day, built up over two to three weeks", "prerequisites": "Irritable bowel or another gut condition: tailored advice first"}$v$::jsonb, benefits = ARRAY[$v$Regular digestion$v$, $v$Lower inflammatory markers in the one trial$v$, $v$Lower mortality across the fibre cohorts$v$, $v$Possibly steadier mood via the gut-brain axis$v$], risks = ARRAY[$v$Raise fibre gradually or expect bloating$v$, $v$Irritable bowel syndrome and other gut conditions need tailored advice; some fermented foods worsen symptoms$v$, $v$The mood claims are early; treat them as a bonus, not a reason$v$], body_md = $v$**Why it matters**
The bacteria in the gut digest what you cannot, train the immune system, make short-chain fatty acids that calm inflammation, and talk to the brain along the vagus nerve. The mood claims are the least settled part of that sentence. The digestion and immunity claims are not.

**Fibre and the mortality data**
Reynolds et al. (2019) pooled 185 cohorts and 58 trials for the Lancet: people eating 25 to 29 g of fibre a day had 15 to 30% lower all-cause and cardiovascular mortality than those eating the least, with the benefit still rising above 30 g. Most adults in Europe eat under 20 g. Vegetables, fruit, legumes, whole grains, nuts and seeds are where it is; supplements deliver fibre without the diversity.

**Diversity**
The American Gut project (McDonald et al. 2018) crowd-sourced stool samples from more than 10,000 people and found that the number of different plants eaten a week predicted microbiome diversity better than whether someone called themselves vegetarian: thirty or more plants a week was the marker. Herbs, spices, seeds and a different bean all count. It is an association from a citizen-science sample, and it is the most useful single rule the field has produced.

**Fermented foods, the surprise**
Wastyk et al. (2021) at Stanford randomised 36 adults to ten weeks of either a high-fibre diet or a diet high in fermented foods: yoghurt, kefir, kimchi, sauerkraut, kombucha. The fermented group's microbiome diversity rose steadily and nineteen inflammatory markers fell. The high-fibre group's diversity did not change in ten weeks, though their microbes shifted toward fibre digestion. It is one small trial. It is also the reason a daily serving of something fermented sits next to the fibre rule rather than behind it.

**How to run it**
Count the plants for one week; most people land near fifteen and can double it with a mixed-bean tin, a handful of seeds and a new vegetable each shop. Add one fermented food a day: live yoghurt or kefir, unpasteurised sauerkraut or kimchi, miso, tempeh. Increase fibre over two or three weeks with plenty of water, or the first week will be uncomfortable.$v$, why_it_matters = $v$The gut is where the Mediterranean pattern does part of its work. Two rules, thirty plants and one fermented food a day, cover most of what the evidence supports, and both are cheap.$v$, try_today = ARRAY[$v$Count the different plants you ate today, herbs and spices included.$v$, $v$Add one fermented food to a meal: kefir, live yoghurt, kimchi or sauerkraut.$v$, $v$Put one new vegetable and a tin of mixed beans in this week's shop.$v$], key_takeaways = ARRAY[$v$Thirty different plants a week is the diversity marker; a tin of mixed beans is six of them.$v$, $v$A small daily serving of fermented food raised diversity and lowered inflammation in the one controlled trial.$v$, $v$Raise fibre slowly, with water.$v$], quiz = $v$[{"q": "In the Stanford trial, which diet raised microbiome diversity in ten weeks?", "choices": ["High fermented foods", "Neither", "High fibre"], "correct": 0, "explain": "Wastyk 2021: the fermented group's diversity rose and nineteen inflammatory markers fell; the fibre group's diversity held still."}, {"q": "What predicted diversity in the American Gut data?", "choices": ["Being vegetarian", "The number of different plants eaten a week", "Taking probiotics"], "correct": 1, "explain": "Thirty or more plants a week; herbs, spices and seeds all count."}, {"q": "At 25 to 29 g of fibre a day, the pooled cohorts found…", "choices": ["Higher mortality", "No effect", "15 to 30% lower all-cause and cardiovascular mortality"], "correct": 2, "explain": "Reynolds 2019, 185 cohorts. Most adults in Europe eat under 20 g."}]$v$::jsonb, references_json = $v$[{"author": "Wastyk, H. C. et al.", "title": "Gut-microbiota-targeted diets modulate human immune status (Cell)", "year": 2021}, {"author": "McDonald, D. et al.", "title": "American Gut: an open platform for citizen science microbiome research (mSystems)", "year": 2018}, {"author": "Reynolds, A. et al.", "title": "Carbohydrate quality and human health: a series of systematic reviews and meta-analyses (Lancet)", "year": 2019}]$v$::jsonb, reflect_prompt = $v$How many different plants did you eat yesterday, and how many of them were the same as the day before?$v$, integrate_prompt = $v$Two weeks of thirty plants and a fermented food. What changed in digestion, and did anything change in mood?$v$, practice_minutes = 5, lesson_number = 9, display_order = 9, course_role = $v$protocol$v$, read_time_min = 3, updated_at = now() WHERE slug = 'gut-health-fiber-fermented';
